def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = dict()
        hits = misses = 0
        lock = RLock()
        root = []
        root[:] = [root] * 2
        nonlocal hits, misses, lock, root

        def MakeCacheKey(*args, **kwds):
            def makeKey(value):
                if isinstance(value, bool):
                    return 1 if value else 0
                elif isinstance(value, str):
                    return repr(value)
                else:
                    return id(value)
            key = ()
            cachekey_values = []
            for arg in args:
                cachekey_values.append(makeKey(arg))
            for key, arg in kwds.items():
                cachekey_values.append((key, makeKey(arg)))
            return "_cachekey:" + sha1(str(cachekey_values).encode()).hexdigest()

        def wrapper(*args, **kwds):
            nonlocal hits, misses, lock, root
            key = MakeCacheKey(*args, **kwds)
            with lock:
                now = timer()
                for (expiry, value) in root:
                    if now >= expiry:
                        root.remove((expiry, value))

                try:
                    (expiry, value) = cache[key]
                    if now < expiry:
                        hits += 1
                        return value
                    else:
                        misses += 1
                except KeyError:
                    misses += 1

            value = func(*args, **kwds)
            with lock:
                cache[key] = (now + ttl, value)
                root.insert(0, (now + ttl, value))
            return value

        if hasattr(wrapper, "__wrapped__"):
            wrapper.__wrapped__ = func

        return update_wrapper(wrapper, func)

    return decorator

