def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        class Memoize:
            def __init__(self, func, maxsize, typed):
                self.maxsize = maxsize
                self.typed = typed
                self.cache = {}
                self.rank = 0

            def __call__(self, *args, **kwargs):
                if typed:
                    key = args[0].__class__, args
                else:
                    key = args

                if key not in self.cache:
                    value = func(*args, **kwargs)
                    self.cache[key] = value
                else:
                    value = self.cache[key]
                    self.rank = (self.rank + 1) % self.maxsize

                return value

        return Memoize(func, maxsize, typed)

    return decorator

