def _normalizeargs(sequence, output=None):
    if isinstance(sequence, (Declaration, tuple)):
        if output is None:
            output = []
        output.append(sequence)
        return output
    elif isinstance(sequence, Interface):
        return [sequence]
    elif isinstance(sequence, implements):
        return [sequence.interface]
    elif isinstance(sequence, list):
        if output is None:
            output = []
        for item in sequence:
            output.extend(_normalizeargs(item))
        return output
    else:
        raise ValueError("Invalid declaration argument")

