def _explore_folder(folder):
    files_grouped_by_name = {}
    for file in folder.iterdir(): #iterate over all files in the folder
        # Get XML basename of each file
        xml_basename = file.name.split('.')[0]
        # If file has already been seen before, append it to the list of related files
        if xml_basename in files_grouped_by_name:
            files_grouped_by_name[xml_basename].append(file)
