def pretty(self, indent=0, debug=False):
    indentation = '  ' * indent
    result = []
    result.append(f'{indentation}<{self.__class__.__name__}>\n')
    for attrib in self:
        if isinstance(attrib, Element):
            result.append(attrib.pretty(indent + 1, debug))
        elif isinstance(attrib, TextContent):
            result.append(attrib.text)
        else:
            result.append(f'{indentation}  {attrib.value}')
    result.append(f'{indentation}</{self.__class__.__name__}>\n')
    if debug:
        result.append(f'{indentation}<DEBUG> {self.debug_str()}')
    return ''.join(result)

