def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool): Whether to also validate every object in the hierarchy
        check_digests (bool): Whether to check the digests of the objects
        show_warnings (bool): Whether to output warnings to the console

    Returns:
        (num_objects, good_objects) - number of objects checked and the number of valid objects found
    """
    # Create a queue to store all the objects in the hierarchy
    queue = deque()
    queue.append(self)

    # Iterate over the objects in the hierarchy and validate them
    num_objects = 0
    good_objects = 0
    while queue:
        obj = queue.popleft()
        num_objects += 1

        # Validate the object
        if validate_objects:
            if obj.is_valid():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"The object {obj} in the hierarchy is not valid.")

        # Check the digest of the object
        if check_digests:
            if not obj.validate_digest():
                if show_warnings:
                    print(f"The object {obj} in the hierarchy has an invalid digest.")

        # Add the object's children to the queue
        for child in obj.children:
            queue.append(child)

    return (num_objects, good_objects)

