def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    # Use REGEX for POSIX platforms
    if platform == 1: # or platform == 'this' and sys.platform != 'win32':
        return re.split(r'\n(?![^\n]*(?:\\{2})*\\[^\n]*$)', s)

    # Use CMD quoting rules for Windows platforms
    elif platform == 0 or platform == 'this' and sys.platform == 'win32':
        import shlex
        return shlex.split(s)

    # Raise ValueError for unknown platforms
    else:
        raise ValueError("Unknown platform: {}".format(platform))

